package com.vynedam.stockai.service;
import com.vynedam.stockai.domain.*; import com.vynedam.stockai.dto.InventoryDtos.*; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.*; import com.vynedam.stockai.repository.*; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class InventoryService { private final BatchRepository batches; private final MaterialRepository materials; private final StockMovementRepository movements; private final WarehouseService warehouses; public InventoryService(BatchRepository b,MaterialRepository m,StockMovementRepository x,WarehouseService w){batches=b;materials=m;movements=x;warehouses=w;} public List<Batch> list(){return batches.findAll();} public Batch create(BatchRequest r,String actor){materials.findById(r.materialId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Material not found"));warehouses.assertOperationalAccess(r.warehouseId(),actor);var b=new Batch();b.batchNumber=r.batchNumber().trim().toUpperCase();b.materialId=r.materialId();b.supplierLot=r.supplierLot();b.warehouseId=r.warehouseId();b.unitId=r.unitId();b.quantity=r.quantity();b.uom=r.uom();b.expiresAt=r.expiresAt();b.barcode=r.barcode();b.receivedAt=Instant.now();b.status=BatchStatus.QUARANTINE;batches.save(b);record(b,MovementType.RECEIPT,b.quantity,null,b.warehouseId,"RECEIPT",actor);return b;} public Batch release(String id){var b=get(id);if(b.status==BatchStatus.REJECTED)throw new ApiException(HttpStatus.CONFLICT,"INVALID_STATE","Rejected batch cannot be released");b.status=BatchStatus.AVAILABLE;return batches.save(b);} public Batch move(MovementRequest r,String actor){var b=get(r.batchId());warehouses.assertOperationalAccess(b.warehouseId,actor);if(r.type()==MovementType.TRANSFER_IN||r.type()==MovementType.TRANSFER_OUT||r.type()==MovementType.RECEIPT)throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_MOVEMENT","Use the dedicated receipt or transfer workflow");if(List.of(MovementType.CONSUMPTION,MovementType.SCRAP,MovementType.DISPATCH).contains(r.type())){if(b.status!=BatchStatus.AVAILABLE)throw new ApiException(HttpStatus.CONFLICT,"BATCH_NOT_AVAILABLE","Only an available batch can be consumed, scrapped, or dispatched");if(b.quantity<r.quantity())throw new ApiException(HttpStatus.CONFLICT,"INSUFFICIENT_STOCK","Quantity exceeds available stock");b.quantity-=r.quantity();if(b.quantity==0)b.status=BatchStatus.CONSUMED;}else b.quantity+=r.quantity();batches.save(b);record(b,r.type(),r.quantity(),b.warehouseId,r.toWarehouseId(),r.reference(),actor);return b;} public Batch get(String id){return batches.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Batch not found"));} private void record(Batch b,MovementType type,double qty,String from,String to,String ref,String actor){var m=new StockMovement();m.batchId=b.id;m.type=type;m.quantity=qty;m.fromWarehouseId=from;m.toWarehouseId=to;m.reference=ref;m.actorId=actor;m.occurredAt=Instant.now();movements.save(m);} }
